import{_ as e,c as t,o as c,b2 as d}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"C7DictTag 字典标签","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/components/通用组件/c7-dict-tag.md","filePath":"docs/frontend/components/通用组件/c7-dict-tag.md"}'),r={name:"docs/frontend/components/通用组件/c7-dict-tag.md"};function n(s,o,g,a,i,l){return c(),t("div",null,[...o[0]||(o[0]=[d('<h1 id="c7dicttag-字典标签" tabindex="-1">C7DictTag 字典标签 <a class="header-anchor vp-link" href="#c7dicttag-字典标签" aria-label="Permalink to &quot;C7DictTag 字典标签&quot;">​</a></h1><p>只读组件：将 <strong><code>modelValue</code></strong>（单值、数组或含分隔符的字符串）按 <strong><code>options</code></strong> 映射为 <strong><code>ElTag</code></strong> 列表，支持 <strong><code>max</code> 折叠（<code>+N</code>）</strong>、<strong><code>collapse</code> 与 Tooltip/Popover</strong>、<strong>未匹配展示</strong> 与 <strong><code>dictType</code> → <code>ElTag.type</code></strong>。</p><p><strong>源码</strong>：<code>quick-ui/src/packages/C7DictTag/index.vue</code><br><strong>Dev 页</strong>：开发服务器启动后访问 <code>/dev/c7-dict-tag-e2e</code></p><h2 id="功能概要" tabindex="-1">功能概要 <a class="header-anchor vp-link" href="#功能概要" aria-label="Permalink to &quot;功能概要&quot;">​</a></h2><ul><li><strong><code>modelValue</code></strong>：<strong><code>number</code> / <code>string</code> / <code>array</code></strong>；<strong><code>string</code></strong> 在 <strong>包含 <code>separator</code></strong> 时拆分（默认 <strong><code>,</code></strong>），<strong>不去重</strong>。</li><li><strong><code>options</code></strong>：行形态 <strong><code>{ label, value }</code></strong>，匹配 <strong><code>String(opt.value) === String(原子)</code></strong> 的首项。</li><li><strong><code>max &gt; 0</code></strong>：仅对 <strong>已匹配</strong> 项编号；前 <strong><code>max</code></strong> 枚展示字典色 tag，溢出 <strong><code>+N</code></strong>（<strong><code>N = 已匹配总数 − max</code></strong>）；<strong><code>mk &gt; max + 1</code></strong> 的位置不占位。</li><li><strong><code>showValue</code></strong>：未匹配时 <strong><code>true</code></strong> → <strong><code>type=info</code></strong> 展示原始值；<strong><code>false</code></strong> → 该位 <strong><code>-</code></strong>。</li><li><strong><code>collapse</code></strong>：<strong><code>true</code></strong> → <strong><code>+N</code></strong> 使用 <strong><code>ElTooltip</code></strong>；<strong><code>false</code></strong> → <strong><code>ElPopover</code>（click）</strong> 展示溢出 <strong><code>label</code></strong> 列表。</li><li><strong><code>dictType</code></strong>：映射 <strong><code>ElTag.type</code></strong>；未知回退 <strong><code>primary</code></strong>。</li><li><strong><code>size</code> / <code>effect</code> / <code>round</code></strong>：透传至相关 <strong><code>ElTag</code></strong>。</li></ul><h2 id="与全局注册" tabindex="-1">与全局注册 <a class="header-anchor vp-link" href="#与全局注册" aria-label="Permalink to &quot;与全局注册&quot;">​</a></h2><p>在 <code>main.js</code> 已调用 <code>installPackages(app)</code> 时，模板中可直接使用 <code>&lt;c7-dict-tag /&gt;</code>（或 <code>&lt;C7DictTag /&gt;</code>）。</p><h2 id="相关规格" tabindex="-1">相关规格 <a class="header-anchor vp-link" href="#相关规格" aria-label="Permalink to &quot;相关规格&quot;">​</a></h2><p>OpenSpec 变更：<code>openspec/changes/ui-c7-dict-tag/specs/ui-c7-dict-tag/spec.md</code></p>',9)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
